package service

import "testing"

func TestDBLightningService_Read(t *testing.T) {
	s := new(DBLightningService)
	t.Run("Pass", func(tt *testing.T) {
		pid, data, err := s.Read("", 9936738, 1003, 5)
		tt.Log(err)
		tt.Logf("PID: %d, Data Length: %d\n", pid, len(data))
		tt.Logf("Data: %s\n", data)
	})
}

